$imageAttrs = static function (mixed $source, string $sizes, mixed $focusX = '', mixed $focusY = '') use ($e, $publicRoot, $themeImageDimensions): string {
    $src=trim((string)$source);$path=(string)(parse_url($src,PHP_URL_PATH)?:'');if($src===''||$path==='')return'';
    $dimensions=$themeImageDimensions[$path]??null;
    if($dimensions===null&&str_starts_with($path,'/media/library/')&&!str_contains($path,'..')){$file=$publicRoot.str_replace('/',DIRECTORY_SEPARATOR,$path);$info=is_file($file)?@getimagesize($file):false;if(is_array($info))$dimensions=[(int)$info[0],(int)$info[1]];}
    $candidates=[];
    if(is_array($dimensions)){
        [$width,$height]=$dimensions;
        if(isset($themeImageDimensions[$path])){foreach([480,800]as$target)if($width>$target)$candidates[$target]=(string)preg_replace('/\.[^\.\/]+$/','-'.$target.'.webp',$path).' '.$target.'w';}
        else{foreach(['thumb'=>320,'medium'=>768,'large'=>1440]as$name=>$target){$candidateWidth=min($width,$target);$candidates[$candidateWidth]=(string)preg_replace('/\.[^\.\/]+$/','-'.$name.'.webp',$path).' '.$candidateWidth.'w';}}
        if(!isset($candidates[$width]))$candidates[$width]=$src.' '.$width.'w';ksort($candidates);
    }
    $attributes='';if($candidates)$attributes.=' srcset="'.$e(implode(', ',array_values($candidates))).'" sizes="'.$e($sizes).'"';
    if(is_array($dimensions))$attributes.=' width="'.(int)$dimensions[0].'" height="'.(int)$dimensions[1].'"';
    $x=in_array((string)$focusX,['left','center','right'],true)?(string)$focusX:'center';$y=in_array((string)$focusY,['top','center','bottom'],true)?(string)$focusY:'center';
    return $attributes.' style="object-position:'.$e($x).' '.$e($y).'"';
};
