<script>(()=>{const popup=document.currentScript.previousElementSibling;if(!popup?.matches('[data-school-popup]'))return;popup.dataset.popupReady='1';const key='eduvixo-popup-'+popup.dataset.popupKey,frequency=popup.dataset.popupFrequency,store=frequency==='once'?localStorage:sessionStorage;let dismissed=false;try{dismissed=frequency!=='always'&&store.getItem(key)==='1'}catch{}if(dismissed){popup.remove();return}document.documentElement.classList.add('school-popup-open');document.body.classList.add('school-popup-open');const onKey=event=>{if(event.key==='Escape')dismiss()},dismiss=()=>{if(frequency!=='always')try{store.setItem(key,'1')}catch{}removeEventListener('keydown',onKey);document.documentElement.classList.remove('school-popup-open');document.body.classList.remove('school-popup-open');popup.remove()};popup.addEventListener('click',event=>{if(!(event.target instanceof Element))return;if(event.target.closest('[data-school-popup-close]')||event.target.matches('.school-popup-backdrop'))dismiss()});addEventListener('keydown',onKey)})()</script>
